import gzip,json,os,collections as C
tot=C.Counter(); imgs=C.Counter(); per=[]
toolres=C.Counter(); toolcalls=C.Counter(); textkinds=C.Counter()
for f in sorted(os.listdir('kept')):
    d=json.load(gzip.open('kept/'+f)); 
    if d['format']!='anthropic': continue
    q=json.loads(d['request']); c=C.Counter()
    c['system']+=len(json.dumps(q.get('system',''))); c['tools']+=len(json.dumps(q.get('tools',[])))
    names={}
    for m in q['messages']:
        cont=m['content'] if isinstance(m['content'],list) else [{'type':'text','text':m['content']}]
        for b in cont:
            t=b.get('type')
            if t=='text':
                k=m['role']+' text'; c[k]+=len(b['text'])
                if m['role']=='user':
                    s=b['text'].lstrip()[:40]; tag=s.split('>')[0][:30] if s.startswith('<') else 'plain'
                    textkinds[tag]+=len(b['text'])
            elif t=='thinking': c['assistant thinking']+=len(b.get('thinking',''))+len(b.get('signature',''))
            elif t=='redacted_thinking': c['assistant thinking']+=len(b.get('data',''))
            elif t=='tool_use': names[b['id']]=b['name']; c['tool call inputs']+=len(json.dumps(b['input'])); toolcalls[b['name']]+=1
            elif t=='image': c['images']+=len(json.dumps(b)); imgs[f]+=1
            elif t=='tool_result':
                n=names.get(b.get('tool_use_id'),'?')
                inner=b.get('content'); inner=inner if isinstance(inner,list) else [{'type':'text','text':str(inner)}]
                for ib in inner:
                    if ib.get('type')=='image': c['images']+=len(json.dumps(ib)); imgs[f]+=1; toolres['(image) '+n]+=len(json.dumps(ib))
                    else: L=len(ib.get('text','') if ib.get('type')=='text' else json.dumps(ib)); c['tool results']+=L; toolres[n]+=L
            else: c['other:'+str(t)]+=len(json.dumps(b))
    u=d['usage']; prompt=u.get('input_tokens',0)+u.get('cache_read_input_tokens',0)+u.get('cache_creation_input_tokens',0)
    per.append((f[:6],len(q['messages']),prompt,sum(c.values()),imgs[f],d['requests_seen']))
    tot+=c
T=sum(tot.values())
print('share of request bytes across 30 biggest kept chats (last request of each):')
for k,v in tot.most_common(): print('  %-22s %5.1f%%  %6.1f MB'%(k,100*v/T,v/1e6))
print('\ntool results by tool (bytes share of all):')
for k,v in toolres.most_common(15): print('  %-34s %5.1f%%'%(k,100*v/T))
print('\nuser text by leading tag:')
for k,v in textkinds.most_common(8): print('  %-32s %5.1f%%'%(k,100*v/T))
print('\ntool calls:',toolcalls.most_common(12))
print('\nper chat: user, messages, prompt tokens, bytes, images, requests seen')
for p in per: print(' ',p)
EOF
