        # own, so a cache_control the client put on its blocks stays where it is.
        if own is None or own == '':
            own = []
        elif isinstance(own, str):
            own = [{'type': 'text', 'text': own}]
        elif not isinstance(own, list):
            raise GatewayError(400, 'invalid_request', f'Field "{field}" must be a string or a list.')
        body[field] = [{'type': 'text', 'text': identity}] + own
    else:
        if own is None or own == '':
            body[field] = identity
        elif isinstance(own, str):
            body[field] = f'{identity}\n\n{own}'
        else:
            raise GatewayError(400, 'invalid_request', f'Field "{field}" must be a string.')


def _scope_cache_key(fmt, body, user_id):
    """Puts the user id in front of the client's cache key. Every user shares
    the backend's one organisation, where OpenAI recommends a key per user to
    prevent cache-hit probing across users; a key the client sends cannot
    then land in another user's."""
    field = CACHE_KEY_FIELD.get(fmt)
    if field not in body:
        return
    key = body[field]
    if not isinstance(key, str) or key == '':
        raise GatewayError(400, 'invalid_request', f'Field "{field}" must be a non-empty string.')
    body[field] = f'{user_id}:{key}'


def _strip_images(fmt, body):
    """Replaces every picture in the conversation with a text note, for a
    backend whose hosts refuse image input. Follows only the fields that hold
    blocks, never a tool call's own arguments."""
    def strip(blocks):
        for i, block in enumerate(blocks):
            if not isinstance(block, dict):
                continue
            if block.get('type') == IMAGE_BLOCK[fmt]:
                blocks[i] = {'type': TEXT_BLOCK[fmt], 'text': IMAGE_NOTE}
                continue
            for field in ('content', 'output'):
                if isinstance(block.get(field), list):
                    strip(block[field])

    conversation = body.get(CONVERSATION_FIELD[fmt])
    if isinstance(conversation, list):
        strip(conversation)


def _set_cache_ttl(body):
    """Puts the lifetime on every cache_control. All of them, because Anthropic
    requires longer lifetimes to come before shorter ones."""
    def visit(node):
        if isinstance(node, list):
            for item in node:
                visit(item)
        elif isinstance(node, dict):
            if isinstance(node.get('cache_control'), dict):
                node['cache_control'] = {**node['cache_control'], 'ttl': CACHE_TTL}
            visit(node.get('content'))

    for field in ('tools', 'system', 'messages'):
        visit(body.get(field))


def _headers(fmt, backend, diagnosed=False) -> Dict[str, str]:
    key = os.environ.get(backend.api_key_env)
    if not key:
        raise ImproperlyConfigured(f'{backend.api_key_env}, the key for a JusPrin v2 {fmt} backend, is not set')
