class PrepareTests(TestCase):
    def setUp(self):
        env = mock.patch.dict('os.environ', {'TEST_KEY': 'k'})
        env.start()
        self.addCleanup(env.stop)

    def sent(self, fmt, aliases, **body):
        raw = json.dumps({'stream': True, **body}).encode()
        return json.loads(prepare(fmt, raw, aliases, 7).body)

    def responses_body(self, picture):
        return dict(model='slicer-basic', input=[
            {'role': 'user', 'content': [{'type': 'input_text', 'text': 'look'}, picture]},
            {'type': 'function_call', 'call_id': 'c1', 'name': 'view', 'arguments': '{"type":"input_image"}'},
            {'type': 'function_call_output', 'call_id': 'c1', 'output': [picture]},
        ])

    def test_pictures_become_a_note_on_a_backend_without_images(self):
        picture = {'type': 'input_image', 'image_url': 'data:image/png;base64,AAAA'}
        sent = self.sent('responses', ALIASES, **self.responses_body(picture))
        note = {'type': 'input_text', 'text': IMAGE_NOTE}
        self.assertEqual(sent['input'][0]['content'], [{'type': 'input_text', 'text': 'look'}, note])
        self.assertEqual(sent['input'][1]['arguments'], '{"type":"input_image"}')
        self.assertEqual(sent['input'][2]['output'], [note])
        self.assertNotIn('AAAA', json.dumps(sent))

    def test_a_backend_with_images_keeps_them(self):
        picture = {'type': 'input_image', 'image_url': 'data:image/png;base64,AAAA'}
        aliases = parse_aliases(two_aliases(basic_images=True))
        sent = self.sent('responses', aliases, **self.responses_body(picture))
        self.assertEqual(sent['input'][0]['content'][1], picture)

    def test_anthropic_pictures_are_stripped_inside_tool_results_too(self):
        config = json.loads(two_aliases())
        config['aliases'][0]['backends']['anthropic']['images'] = False
        picture = {'type': 'image', 'source': {'type': 'base64', 'media_type': 'image/png', 'data': 'AAAA'}}
        sent = self.sent('anthropic', parse_aliases(json.dumps(config)), model='slicer-1', max_tokens=1, messages=[
            {'role': 'user', 'content': [picture]},
            {'role': 'assistant', 'content': [{'type': 'tool_use', 'id': 'c', 'name': 'n', 'input': picture}]},
            {'role': 'user', 'content': [{'type': 'tool_result', 'tool_use_id': 'c', 'content': [picture]}]},
        ])
        note = {'type': 'text', 'text': IMAGE_NOTE}
        self.assertEqual(sent['messages'][0]['content'], [note])
        self.assertEqual(sent['messages'][1]['content'][0]['input'], picture)
        self.assertEqual(sent['messages'][2]['content'][0]['content'], [note])

    def test_every_cache_control_lasts_five_minutes(self):
        ephemeral = {'type': 'ephemeral'}
        five_minutes = {'type': 'ephemeral', 'ttl': '5m'}
        sent = self.sent('anthropic', ALIASES, model='slicer-1', max_tokens=1,
                         tools=[{'name': 't', 'input_schema': {}, 'cache_control': ephemeral}],
                         system=[{'type': 'text', 'text': 's', 'cache_control': ephemeral}],
                         messages=[{'role': 'user', 'content': [
                             {'type': 'tool_result', 'tool_use_id': 'c',
                              'content': [{'type': 'text', 'text': 'r', 'cache_control': ephemeral}]},
                             {'type': 'text', 'text': 'm', 'cache_control': ephemeral}]}])
        self.assertEqual(sent['tools'][0]['cache_control'], five_minutes)
        self.assertEqual(sent['system'][-1]['cache_control'], five_minutes)
        self.assertEqual(sent['messages'][0]['content'][1]['cache_control'], five_minutes)
        self.assertEqual(sent['messages'][0]['content'][0]['content'][0]['cache_control'], five_minutes)

    def test_the_diagnosis_beta_joins_the_backends_own(self):
        aliases = parse_aliases(json.dumps({'aliases': [{
            'id': 'slicer-1', 'label': 'Slicer 1', 'tier': 'expert', 'credits': 5, 'efforts': [], 'default_effort': None,
            'backends': {'anthropic': {'base_url': UPSTREAM, 'model': 'm', 'api_key_env': 'TEST_KEY', 'effort_map': {},
                                       'headers': {'anthropic-beta': 'other-beta'}}},
            'groups': [{'name': 'g', 'format': 'anthropic', 'percent': 100}]}]}))
