        r=call('messages',{**base,'messages':nocache(msgs)})
        res[arm]=r
        if 'usage' in r: total+=cost(r['usage'])
    # does the swapped arm's new thinking block stay valid on the next request the gateway would build?
    rb=res['swapped']
    chk=None
    if 'content' in rb:
        nxt=M+[{'role':'assistant','content':rb['content']}]
        uses=[b for b in rb['content'] if b['type']=='tool_use']
        nxt.append({'role':'user','content':[{'type':'tool_result','tool_use_id':b['id'],'content':'{"ok":true}'} for b in uses] or [{'type':'text','text':'ok'}]})
        nxt=run(nxt)
        for m in nxt[:-2]:
            if m['role']=='assistant' and isinstance(m['content'],list):
                m['content']=[b for b in m['content'] if b['type'] not in ('thinking','redacted_thinking')]
        b2={**base,'messages':nocache(nxt)}; b2.pop('max_tokens'); b2.pop('output_config',None)
        b2['thinking']={'type':'adaptive','block_binding':{'prefix_mismatch_behavior':'error'}}
        chk=call('messages/count_tokens',b2)
    out.append({'file':f,'k':k,'res':res,'next_check':chk})
    print(f[-20:],k,'cost so far $%.2f'%total,flush=True)
json.dump(out,open('live_out.json','w'))
print('total $%.2f'%total)
