import json, subprocess, base64, urllib.request, urllib.parse, sys
ctx='gke_tsdtechnology_us-central1-c_tsd'
dep=json.loads(subprocess.check_output(['kubectl','--context',ctx,'get','deploy','tsdws-prod','-o','json']))
env={e['name']:e.get('value') for e in dep['spec']['template']['spec']['containers'][0]['env']}
auth=base64.b64encode(f"{env['LANGFUSE_PUBLIC_KEY']}:{env['LANGFUSE_SECRET_KEY']}".encode()).decode()
host=env['LANGFUSE_HOST'].rstrip('/')
def get(path, **p):
    r=urllib.request.Request(f'{host}{path}?'+urllib.parse.urlencode(p),headers={'Authorization':'Basic '+auth})
    return json.load(urllib.request.urlopen(r,timeout=120))
if sys.argv[1]=='obs':
    b=get('/api/public/v2/observations',fromStartTime='2026-11-25T12:00:00Z',toStartTime='2026-11-25T12:30:00Z',type='GENERATION',limit=50,fields='core,basic,usage,metadata,model')
    for o in b['data']:
        if str(o.get('name','')).startswith('jusprin-v2-'):
            print(json.dumps({k:o.get(k) for k in ('name','model','providedModelName','internalModelId','usageDetails','costDetails','totalCost')}))
else:
    page=1
    while True:
        b=get('/api/public/models',page=page,limit=100)
        for m in b['data']:
            if any(s in (m.get('modelName') or '').lower() for s in ('sonnet','deepseek')):
                print(json.dumps({k:m.get(k) for k in ('id','modelName','matchPattern','isLangfuseManaged','prices','pricingTiers')})[:1500])
        if page>=b['meta']['totalPages']: break
        page+=1

