import gzip,json,os,copy,subprocess,base64,urllib.request,sys,time
exec(open('check12.py').read().split("def one(path):")[0].replace("import gzip,json,os,sys,copy,re,multiprocessing as mp","import re"))
s=json.loads(subprocess.check_output(['kubectl','--context','gke_tsdtechnology_us-central1-c_tsd','get','secret','jusprin-v2-gateway-prod','-o','json']))
key=base64.b64decode(s['data']['JUSPRIN_ANTHROPIC_API_KEY']).decode()
BETA='thinking-binding-controls-2026-08-01'
def call(path,body,beta=BETA):
    h={'x-api-key':key,'anthropic-version':'2023-06-01','content-type':'application/json','anthropic-beta':beta}
    r=urllib.request.Request('https://api.anthropic.com/v1/'+path,data=json.dumps(body).encode(),headers=h)
    for a in range(4):
        try: return json.load(urllib.request.urlopen(r,timeout=600))
        except urllib.error.HTTPError as e:
            if e.code in (429,529,500): time.sleep(10*(a+1)); continue
            return {'http_error':e.code,'body':e.read().decode()[:600]}
def nocache(msgs):
    msgs=copy.deepcopy(msgs)
    def v(n):
        if isinstance(n,list): [v(i) for i in n]
        elif isinstance(n,dict):
            n.pop('cache_control',None); v(n.get('content'))
    v(msgs); return msgs
def cost(u):
    return (u['input_tokens']*2+u.get('cache_read_input_tokens',0)*0.1+u.get('cache_creation_input_tokens',0)*2.5+u['output_tokens']*10)/1e6
cases=json.load(open('cases.json')); out=[]; total=0
