  // A message's bubble, or null for a tool-only reply that has nothing to
  // say. A file's load report is for the model: the person sees the card of
  // what OrcaSlicer said only when the Agent could not speak about it.
  // Otherwise the event that started the Agent's turn gets a row of its own
  // when the load replaced the project, as the Chat/System Line; an import
  // into the open project has its change row ("Import Object: …") already.
  const bubble = (message: Message, after?: ReactNode): ReactNode => {
    if (message.role === 'note' && message.fileReport) {
      if (message.fileReportCard) return <FileNotesCard report={message.fileReport} />;
      return message.fileReport.projectOpened ? openedLine(message, message.fileReport, messages[0]?.id === message.id) : null;
    }
    // Chat/Receipt: a preset the person saved from a proposal, in the same
    // words every time, from what the app saved. Undo takes the save back,
    // and the receipt stays to say so, as an added printer's does.
    if (message.role === 'note' && message.receipt) {
      const receipt = message.receipt;
      const removed = receipt.undone && receipt.undo?.newCopy;
      const preset = receipt.name;
      // Only a removed copy names it, and a copy always has its Undo.
      const earlier = removed ? receipt.undo!.label : '';
      return (
        <div className={receipt.undone ? 'printer-added printer-added-removed' : 'printer-added'} role="status">
          <span className="printer-notice-heading">
            <span className={`jp-icon jp-icon-${receipt.undone ? 'rotate-ccw' : 'check'}`} aria-hidden="true" />
            <span className="printer-added-caption">
              {removed ? <Trans>Removed: <span className="printer-added-name">{preset}</span></Trans>
                : receipt.undone ? <Trans>Undone: <span className="printer-added-name">{preset}</span></Trans>
                : <Trans>Saved: <span className="printer-added-name">{preset}</span></Trans>}
            </span>
          </span>
          {receipt.undone ? (
            <span className="printer-notice-body">
              {removed ? t`Deleted from your filaments. This test uses ${earlier} again.` : t`Its earlier values are back.`}
            </span>
          ) : (
            <span className="printer-added-detail">
              <small>{receipt.detail}</small>
              {receipt.undo && onUndoReceipt && !readOnly && (
                <button type="button" className="panel-link-button printer-added-undo" disabled={replyDisabled}
                  onClick={() => onUndoReceipt(message.id)}>
                  <Trans>Undo</Trans>
                </button>
              )}
            </span>
          )}
        </div>
      );
    }
    if (message.role === 'note')
      return (
        <div className="message note" role="status">
          {/* The colour a change landed on, drawn and never named: the
              app holds a colour as a value, not a word. */}
          {message.swatch && <span className="note-swatch" style={{ background: message.swatch }} aria-hidden="true" />}
          {/* One line; the whole of it stays in the tooltip. */}
          <span className="note-text" title={message.text}>{message.text}</span>
        </div>
        // binds the port for a moment, which could cost discovery its own bind.
        const DiscoveryPort port    = m_backend.discovery_port();
        const bool          changed = port != m_search->port;
        m_search->port              = port;
        if (port == DiscoveryPort::Ours)
            m_search->said_none = true;
        if (m_status_call) {
            answer_status_call(info);
            return;
        }
        // Nothing heard is in the result of the call that listened; only a
        // port that changed since is news.
        if (!changed || port == DiscoveryPort::Ours)
            return;
        note = port == DiscoveryPort::Taken ? kPortTaken : kNotListening;
    }
    m_host.post_note(note);
    m_host.session_changed();
    m_host.start_turn();
}

    if (!plate_label.empty())
